import Foundation
import Observation

@Observable
final class FeedModel {            // main-actor isolated by default in your target
    var items: [Item] = []
    var isLoading = false
    var error: Error?

    func load() async {
        guard !isLoading else { return }
        isLoading = true
        error = nil
        defer { isLoading = false }

        do {
            items = try await Self.fetchItems(from: feedURL)
        } catch {
            self.error = error
        }
    }

    @concurrent
    private static func fetchItems(from url: URL) async throws -> [Item] {
        let (data, _) = try await URLSession.shared.data(from: url)
        return Parser.parse(data)
    }
}
```

