import Foundation
import Observation

@Observable
final class FeedModel {
    var items: [Item] = []
    var isLoading = false
    var error: (any Error)?

    func load() async {
        guard !isLoading else { return }   // `await` lets other callers in, so guard against double loads
        isLoading = true
        defer { isLoading = false }

        do {
            let (data, _) = try await URLSession.shared.data(from: feedURL)
            items = Parser.parse(data)
            error = nil
        } catch is CancellationError {
            // The view went away; nothing to report.
        } catch let urlError as URLError where urlError.code == .cancelled {
            // Same case, surfaced by URLSession.
        } catch {
            self.error = error
        }
