  keyOf(req: IncomingRequest): string | undefined;   // undefined => 401 or skip, see questions
}
export function rateLimit(limiter: RateLimiter, opts: RateLimitMiddlewareOptions): Middleware;

// ── rate-limiter/algorithm.ts (internal, not exported from index) ──
/** Pure: given previous/current window counts and elapsed time in the window,
 *  compute the weighted count, the verdict and the retry delay. Unit-testable without Redis. */
function decide(state: WindowState, nowMs: number, policy: Policy): { decision: Decision; next: WindowState };
interface WindowState { prevCount: number; currCount: number; windowStartMs: number }

// ── rate-limiter/redis-script.ts (internal) ───────────
/** One Lua script: reads TIME from Redis, applies the same logic as decide(),
 *  writes the new counts, sets PEXPIRE to 2×windowMs. Returns [allowed, remaining, retryAfterMs, resetAfterMs]. */
function runCheck(redis: RedisLike, redisKey: string, policy: Policy): Promise<Decision>;
function redisKeyFor(prefix: string, key: ApiKeyId): string;   // hashes the key; raw keys never reach Redis
```

Decisions:

- **Algorithm: sliding-window counter.** It stores two integers per key and smooths the boundary burst that a fixed window allows, where a client could send 200 requests across a minute boundary. Its cost is an approximate count at the edges.
- **One atomic Lua call per request.** This is one round trip and no race. Callers never coordinate `get`, `incr` and `expire` themselves.
- **Time comes from Redis `TIME`.** This removes clock skew between the 4 instances.
- **Keys expire after `2 × windowMs`.** Idle keys clean themselves up, and no sweeper is needed.
- **Store failures are handled inside `check`.** Callers never see a Redis error. The fail-open or fail-closed choice is made once, in the config.
- **Hide the Redis protocol and header format.** `RedisLike` is structural, so the public API exposes no Redis client types. HTTP header names stay in `http.ts`.
- **The public surface is `createRateLimiter`, `check`, `rateLimit` and the types.** The algorithm, script and key hashing are all private.
- **The `decide` / Lua duplication is a risk.** `decide` is the pure reference model. Test the Lua script against it with the same inputs. If the duplication bothers you, drop `decide` and test the Lua only, against a real Redis.

## Synthesis decision

There was no arena run, so there was no synthesis. This is a single candidate that I chose over the alternatives below.

## Tradeoffs accepted

- We accept a slightly approximate count at window edges in exchange for O(1) memory per key and no burst-at-boundary problem.
- We accept a Redis round trip on every request (about 1 ms on a local network) in exchange for an exact shared limit.
- We accept that fail-open can briefly exceed the limit during a Redis outage, in exchange for the API staying up.

## Alternatives considered

- **Per-instance local counters with a limit of 25 each, or periodic sync.** There are no Redis calls, but the limit is wrong whenever the load balancer is uneven. It either under-serves or over-serves, and the sync logic leaks into the API.
- **Sliding-window log (ZSET per key).** It is exact, but memory is O(limit) per key and each request does more work. It has the same interface, so it costs more for no caller-visible benefit.
- **Fixed window (`INCR` + `EXPIRE`).** It is the simplest option, but it allows 2× bursts at window boundaries. If you accept that, it is a drop-in replacement behind `check`.
- **Token bucket in Lua.** It is also a good fit. Choose it if you want to allow deliberate bursts. The interface doesn't change.

## Open questions and risks

- Should Redis outages fail open or fail closed? I'd default to fail-open for a general API.
- What should happen to requests with no API key? Options are 401, a shared anonymous bucket, or an IP-based limit.
- Do you use Redis Cluster? If so, the single-key Lua script is fine, because it touches only one key.
- Is a hard cap of exactly 100 required, or is "about 100" acceptable? A hard cap pushes toward the sliding-window log.
- Which framework are you on (Express, Fastify, or something else)? It only affects `http.ts`.
- Do different keys or plans need different limits? If so, `Policy` would become `policyFor(key)`. I've left that out for now.

