   *  store failures resolve according to `onStoreError`. Rejected requests are not counted. */
  check(keyId: string): Promise<RateLimitDecision>;
}

export interface RateLimiterOptions {
  redis: Redis;                         // injected client, so tests can swap it
  policy: RateLimitPolicy;
  onStoreError: "allow" | "deny";       // explicit choice, with no default
  keyPrefix?: string;                   // default "rl:"
}

