/** One Lua script, one round trip. Runs atomically in Redis and uses Redis TIME,
 *  so the 4 instances' clocks never matter. */
interface WindowScriptResult { allowed: 0 | 1; count: number; oldestMs: number }

function runWindowScript(redis: Redis, redisKey: string, policy: RateLimitPolicy): Promise<WindowScriptResult>;

/** Pure: script result → domain decision. This is the unit-testable core. */
