// ---- rate-limiter/index.ts (the whole public surface) ----

/** Hash/ID of the key, never the raw secret. Brand prevents passing arbitrary strings. */
export type ApiKeyId = string & { readonly __brand: "ApiKeyId" };

/** Invariants: both positive integers; limit <= 10_000. Validated in createRateLimiter. */
export interface Policy {
  readonly limit: number;       // requests per window
  readonly windowMs: number;
}

export interface RateLimiterConfig {
  readonly redis: RedisLike;                 // minimal structural type: only `eval`/`evalsha`
  readonly policy: Policy;
  readonly onStoreError: "allow" | "deny";   // required; no silent default
  readonly keyPrefix?: string;               // default "rl"
}

export type Decision =
  | { kind: "allowed"; limit: number; remaining: number; resetAfterMs: number }
  | { kind: "limited"; limit: number; retryAfterMs: number }
  | { kind: "bypassed"; reason: "store-unavailable" };  // only produced when onStoreError = "allow"

export interface RateLimiter {
  /** Atomic across all instances. Never throws on store failure; applies onStoreError. */
  check(key: ApiKeyId, opts?: { cost?: number }): Promise<Decision>;
}

export function createRateLimiter(config: RateLimiterConfig): RateLimiter; // throws on invalid Policy

// ---- rate-limiter/http.ts (framework adapter; the only file that knows about HTTP) ----
export function rateLimit(
  limiter: RateLimiter,
  keyOf: (req: Request) => ApiKeyId | undefined,  // undefined => not our concern, pass through
): Middleware;                                    // sets headers, returns 429 when limited

export function rateLimitHeaders(d: Decision): Record<string, string>;
// RateLimit-Limit / -Remaining / -Reset, plus Retry-After when limited

// ---- private, not exported ----
// rate-limiter/gcra.lua      single atomic script; reads Redis TIME, writes one key with PEXPIRE
// rate-limiter/redis-store.ts  loads script (EVALSHA with NOSCRIPT fallback), parses reply -> Decision
```

**Data structure.** There is one Redis key per API key, `rl:{keyId}`. It holds a single number, the GCRA "theoretical arrival time". The key expires after `windowMs`, so idle keys clean themselves up. Instances share no state except this key.

**Data flow.** `check` calls one Lua script, which reads Redis `TIME`, computes the decision, updates the key and returns a tuple. The store parses the tuple into a `Decision`. That is one round trip and a short call chain.

**Depth.** The public surface is `createRateLimiter` and `check`, plus a thin HTTP adapter. The algorithm, Lua, script caching, time source, TTLs, key layout and error policy are all hidden.

## Alternatives considered
- **A. Fixed window (`INCR` + `EXPIRE`).** This is the simplest option. It allows up to 200 requests across a window boundary. `INCR` and `EXPIRE` are also not atomic unless you script them, and it can't give an exact `Retry-After`. It lost on correctness.
- **B. Sliding-window log (a sorted set per key).** It's exact, but it uses O(limit) memory per key and costs more per call. It lost on cost.
- **C. GCRA / token bucket (chosen).** It uses O(1) state, is exact enough, is atomic in one script and gives a precise `retryAfterMs`. Because the algorithm is hidden behind `check`, swapping it later doesn't change any caller.

I also considered exposing a `Store` interface so the algorithm could be tested in memory. I dropped it. It would be a pass-through layer that leaks the storage design. Test against real Redis instead.

## Tradeoffs accepted
- GCRA with burst 100 lets a client send 100 requests at once and then refills at about 1 per 600 ms. That is token-bucket behavior, not "100 in each calendar minute". If you need strict window semantics, use a sliding-window counter behind the same interface.
- The decision logic lives only in Lua, so it's single-sourced but needs a Redis instance (or a container) in tests.
- Fail-open on a Redis outage favors availability over strict enforcement. The `bypassed` variant makes that visible so you can alert on it.

## Open questions and risks
- Which web framework are you on? I assumed an Express/Fetch-style `Request` and `Middleware`.
- Is Redis a single node, Sentinel or Cluster? A single key per script is safe in all three.
- Should the fail-open vs fail-closed choice differ by endpoint?
- Do you need different limits per key or tier? `Policy` would then become `policyFor(key)`, which I left out because it isn't in the requirements.
- Is the raw API key already hashed into an `ApiKeyId` upstream? If not, add a small `toApiKeyId(raw)` function. Don't store raw keys in Redis.

