import {
  AbsoluteFill, Sequence, interpolate, spring,
  useCurrentFrame, useVideoConfig, Easing,
} from "remotion";

const BG = "#0b0f19";
const ACCENT = "#5b8cff";
const font = "Inter, system-ui, sans-serif";

const Hook: React.FC = () => {
  const frame = useCurrentFrame();
  const text = "DELETE FROM orders;";
  const typed = text.slice(0, Math.floor(frame / 3));
  const wiped = frame > 90;
  const rows = wiped
    ? 0
    : 2481902;
  return (
    <AbsoluteFill style={{ background: wiped ? "#2a0a0a" : BG, justifyContent: "center", alignItems: "center", fontFamily: "monospace", color: "#e6e6e6" }}>
      <div style={{ fontSize: 64 }}>
        <span style={{ color: ACCENT }}>&gt; </span>{typed}
        <span style={{ opacity: frame % 20 < 10 ? 1 : 0 }}>▍</span>
      </div>
      <div style={{ fontSize: 40, marginTop: 60, color: wiped ? "#ff5b5b" : "#888" }}>
        orders: {rows.toLocaleString()} rows
      </div>
    </AbsoluteFill>
  );
};

const Title: React.FC = () => {
  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();
  const s = spring({ frame, fps, config: { damping: 15 } });
  return (
    <AbsoluteFill style={{ background: BG, justifyContent: "center", alignItems: "center", fontFamily: font, color: "white" }}>
      <div style={{ fontSize: 140, fontWeight: 800, transform: `scale(${0.8 + 0.2 * s})`, opacity: s }}>
        Snapshots
      </div>
      <div style={{ fontSize: 44, marginTop: 24, color: "#aab4cc", opacity: interpolate(frame, [20, 40], [0, 1], { extrapolateRight: "clamp" }) }}>
        Roll back to any minute in the last 7 days.
      </div>
    </AbsoluteFill>
  );
};

const Timeline: React.FC = () => {
  const frame = useCurrentFrame();
  const { durationInFrames } = useVideoConfig();
  const p = interpolate(frame, [30, durationInFrames - 120], [0, 1], {
    easing: Easing.inOut(Easing.cubic),
    extrapolateLeft: "clamp", extrapolateRight: "clamp",
  });
  const W = 1400;
  const x = W * (1 - p);                       // playhead moves right -> left
  const minutesBack = Math.round(p * 4350);    // demo value: ~3 days
  const d = Math.floor(minutesBack / 1440);
  const h = Math.floor((minutesBack % 1440) / 60);
  const m = minutesBack % 60;
  const restored = frame > durationInFrames - 100;
  const bar = interpolate(frame, [durationInFrames - 100, durationInFrames - 30], [0, 100], {
    extrapolateLeft: "clamp", extrapolateRight: "clamp",
  });
  const rows = Math.round(interpolate(p, [0, 1], [0, 2481902]));

  return (
    <AbsoluteFill style={{ background: BG, fontFamily: font, color: "white", alignItems: "center", justifyContent: "center" }}>
      <div style={{ fontSize: 56, marginBottom: 60 }}>
        −{d}d {h}h {m}m
